) AS v(rc_id, full_name, status_before, result, result_source);

-- ---------------------------------------------------------------------------
-- PRE-FLIGHT
-- ---------------------------------------------------------------------------
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM ca0240_result;
  IF n <> 152 THEN RAISE EXCEPTION 'PRE: % result rows listed, expected 152', n; END IF;

  -- Each row is the row it claims: id, name, a Utah 2026-06-23 primary, not a U.S. House race, and its
  -- status either as authored or (re-run, withdrawals only) already 'withdrawn' by this file.
  SELECT count(*) INTO n
    FROM ca0240_result c
    JOIN essentials.race_candidates rc ON rc.id = c.rc_id AND rc.full_name = c.full_name
                                      AND (rc.candidate_status = c.status_before
                                           OR (c.result = 'withdrew' AND rc.candidate_status = 'withdrawn'))
    JOIN essentials.races ra ON ra.id = rc.race_id AND ra.position_name NOT LIKE 'U.S. House%'
    JOIN essentials.elections e ON e.id = ra.election_id AND e.election_type = 'primary'
                               AND e.state = 'UT' AND e.election_date = '2026-06-23';
  IF n <> 152 THEN RAISE EXCEPTION 'PRE: only % of 152 rows match id / name / status / race', n; END IF;

  SELECT count(*) INTO n FROM ca0240_result c JOIN essentials.race_candidates rc ON rc.id = c.rc_id
   WHERE NOT (rc.result IS NULL OR (rc.result = c.result AND rc.result_source = c.result_source));
  IF n <> 0 THEN RAISE EXCEPTION 'PRE: % rows already carry a different result', n; END IF;

  -- Nothing unreviewed: every stale non-House Utah primary row is here, or is the one held row.
  SELECT count(*) INTO n
    FROM essentials.race_candidates rc
    JOIN essentials.races ra ON ra.id = rc.race_id AND ra.position_name NOT LIKE 'U.S. House%'
    JOIN essentials.elections e ON e.id = ra.election_id AND e.election_type = 'primary'
                               AND e.state = 'UT' AND e.election_date = '2026-06-23'
   WHERE rc.result IS NULL AND rc.candidate_status <> 'withdrawn'
     AND rc.id NOT IN (SELECT rc_id FROM ca0240_result)
     AND NOT (ra.position_name = 'Salt Lake County Recorder' AND rc.full_name = 'Rashelle Hobbs');
  IF n <> 0 THEN RAISE EXCEPTION 'PRE: % stale Utah primary rows were not reviewed', n; END IF;

  RAISE NOTICE 'CA_0240 pre-flight OK';
END $$;

-- ---------------------------------------------------------------------------
-- Record the results. Guarded on result IS NULL.
-- ---------------------------------------------------------------------------
UPDATE essentials.race_candidates rc
   SET result             = c.result,
       result_source      = c.result_source,
       result_recorded_at = '2026-09-24T00:00:00Z'
  FROM ca0240_result c
 WHERE rc.id = c.rc_id
   AND rc.result IS NULL;

-- A withdrawal needs both columns (Phase 167 rule 6).
UPDATE essentials.race_candidates rc
   SET candidate_status = 'withdrawn'
  FROM ca0240_result c
 WHERE rc.id = c.rc_id AND c.result = 'withdrew' AND rc.candidate_status <> 'withdrawn';

-- ---------------------------------------------------------------------------
-- VERIFY
-- ---------------------------------------------------------------------------
DO $$
DECLARE n int;
BEGIN
  SELECT count(*) INTO n FROM ca0240_result c JOIN essentials.race_candidates rc ON rc.id = c.rc_id
   WHERE rc.result = c.result AND rc.result_source = c.result_source AND rc.result_recorded_at IS NOT NULL
     AND rc.candidate_status = CASE WHEN c.result = 'withdrew' THEN 'withdrawn' ELSE c.status_before END;
  IF n <> 152 THEN RAISE EXCEPTION 'POST: % of 152 rows in the expected end state', n; END IF;

  SELECT count(*) INTO n FROM ca0240_result WHERE result = 'won';
  IF n <> 128 THEN RAISE EXCEPTION 'POST: % won, expected 128', n; END IF;
  -- At most one nominee per party race.
  SELECT count(*) INTO n
    FROM (SELECT ra.id FROM ca0240_result c JOIN essentials.race_candidates rc ON rc.id = c.rc_id
            JOIN essentials.races ra ON ra.id = rc.race_id
           WHERE c.result = 'won' GROUP BY ra.id, coalesce(ra.primary_party, '') HAVING count(*) > 1) x;
  IF n <> 0 THEN RAISE EXCEPTION 'POST: % Utah primary races have two winners', n; END IF;

  -- The held row is untouched.
  SELECT count(*) INTO n FROM essentials.race_candidates rc JOIN essentials.races ra ON ra.id = rc.race_id
    JOIN essentials.elections e ON e.id = ra.election_id
   WHERE e.state = 'UT' AND e.election_date = '2026-06-23' AND ra.position_name = 'Salt Lake County Recorder'
     AND rc.full_name = 'Rashelle Hobbs' AND rc.result IS NULL;
  IF n <> 1 THEN RAISE EXCEPTION 'POST: the held Hobbs row changed'; END IF;

  RAISE NOTICE 'CA_0240 applied: 152 Utah primary results (128 won, 16 lost, 5 withdrew, 3 not_nominated); 1 held';
END $$;

COMMIT;
